library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use std.textio.all;
use ieee.std_logic_textio.all;

use work.cordic_test_params_pkg.all;

-- Testbench for cordic_atan2 (pipelined vectoring-mode atan2).
--
-- Config (DATA_WIDTH, ITERATIONS, TOLERANCE, vector count) comes from
-- cordic_test_params_pkg, auto-generated by cordic_atan2_generator.py
-- (reference model = cv::fastAtan2 / numpy). Vectors:
-- testbenches/cordic_vectors.hex, per line as DATA_WIDTH-bit hex: x  y  expected_angle.
--
-- Self-checking with an expected-value queue (latency ITERATIONS+2). The angle
-- is compared with a wrap-aware angle_diff against TEST_TOLERANCE (a few ULPs at
-- 24-bit -- CORDIC's resolution limit). Tracks/reports the worst diff and fails
-- (severity failure) on any out-of-tolerance result.
entity cordic_atan2_tb is
end entity;

architecture sim of cordic_atan2_tb is
    constant CLK_PERIOD : time    := 4 ns;
    constant DATA_WIDTH : natural := TEST_DATA_WIDTH;
    constant ITERATIONS : natural := TEST_ITERATIONS;
    constant LATENCY    : natural := ITERATIONS + 2;
    constant DRAIN_CYCLES : natural := LATENCY + 4;
    constant VECTOR_FILE : string := "testbenches/cordic_vectors.hex";

    -- Tolerance: CORDIC produces ~16-bit angle precision after 16 iterations.
    -- At DATA_WIDTH > 16, the lower bits are below CORDIC's actual resolution.
    -- Allow errors up to a few ULPs at full DATA_WIDTH; for DATA_WIDTH<=16,
    -- this means essentially exact.
    constant TOLERANCE : natural := TEST_TOLERANCE;

    signal clk     : std_logic := '0';
    signal rst     : std_logic := '1';
    signal valid_i : std_logic := '0';
    signal x_i     : signed(DATA_WIDTH-1 downto 0) := (others => '0');
    signal y_i     : signed(DATA_WIDTH-1 downto 0) := (others => '0');
    signal valid_o : std_logic;
    signal angle_o : signed(DATA_WIDTH-1 downto 0);

    -- Expected value queue (circular buffer, sized > LATENCY)
    constant QUEUE_DEPTH : natural := LATENCY * 4;
    type sig_arr_t is array (natural range <>) of signed(DATA_WIDTH-1 downto 0);
    signal exp_queue : sig_arr_t(0 to QUEUE_DEPTH-1);
    signal exp_wr    : natural := 0;
    signal exp_rd    : natural := 0;

    signal errors    : natural := 0;
    signal checks    : natural := 0;
    signal max_error : natural := 0;
    signal done      : boolean := false;

    -- Compute absolute difference modulo the full-circle wrap
    function angle_diff(a, b : signed) return natural is
        constant FULL_CIRCLE : integer := 2**(DATA_WIDTH-1);   -- +pi maps to 2^(W-2);
                                                                -- full circle is 2 * 2^(W-2)
        variable d : integer;
    begin
        d := abs(to_integer(a) - to_integer(b));
        -- Handle wrap: -pi and +pi are the same angle
        if d > FULL_CIRCLE / 2 then
            d := FULL_CIRCLE - d;
        end if;
        return d;
    end function;

begin

    dut : entity work.cordic_atan2
        generic map (
            DATA_WIDTH => DATA_WIDTH,
            ITERATIONS => ITERATIONS
        )
        port map (
            clk     => clk,
            rst     => rst,
            valid_i => valid_i,
            x_i     => x_i,
            y_i     => y_i,
            angle_o => angle_o,
            valid_o => valid_o
        );

    clk <= not clk after CLK_PERIOD/2 when not done else '0';

    stim : process
        file     vec_file : text open read_mode is VECTOR_FILE;
        variable line_in  : line;
        variable hex_v    : std_logic_vector(DATA_WIDTH-1 downto 0);
        variable x_var    : signed(DATA_WIDTH-1 downto 0);
        variable y_var    : signed(DATA_WIDTH-1 downto 0);
        variable exp_var  : signed(DATA_WIDTH-1 downto 0);
    begin
        rst <= '1';
        wait for 5 * CLK_PERIOD;
        rst <= '0';
        wait until rising_edge(clk);

        for vec_idx in 0 to TEST_N_VECTORS-1 loop
            readline(vec_file, line_in);

            hread(line_in, hex_v); x_var   := signed(hex_v);
            hread(line_in, hex_v); y_var   := signed(hex_v);
            hread(line_in, hex_v); exp_var := signed(hex_v);

            x_i     <= x_var;
            y_i     <= y_var;
            valid_i <= '1';

            exp_queue(exp_wr mod QUEUE_DEPTH) <= exp_var;
            exp_wr <= exp_wr + 1;

            wait until rising_edge(clk);
        end loop;

        valid_i <= '0';

        wait for DRAIN_CYCLES * CLK_PERIOD;

        report "Checked " & to_string(checks) &
               " vectors, " & to_string(errors) & " errors. " &
               "Max angle diff: " & to_string(max_error);
        assert errors = 0 report "TEST FAILED" severity failure;
        report "TEST PASSED" severity note;
        done <= true;
        wait;
    end process;

    check : process(clk)
        variable expected : signed(DATA_WIDTH-1 downto 0);
        variable diff     : natural;
    begin
        if rising_edge(clk) then
            if valid_o = '1' then
                expected := exp_queue(exp_rd mod QUEUE_DEPTH);
                diff := angle_diff(angle_o, expected);

                if diff > max_error then
                    max_error <= diff;
                end if;

                if diff > TOLERANCE then
                    if errors < 20 then  -- limit verbose error output
                        report "MISMATCH at check " & to_string(checks) &
                               ": got " & to_string(to_integer(angle_o)) &
                               ", expected " & to_string(to_integer(expected)) &
                               ", diff = " & to_string(diff)
                            severity error;
                    end if;
                    errors <= errors + 1;
                end if;
                checks <= checks + 1;
                exp_rd <= exp_rd + 1;
            end if;
        end if;
    end process;

end architecture;